 45→export default function Dashboard() {
 46→    const { exploitation, unreadRegulationsCount } = usePage<{ exploitation: Exploitation | null; unreadRegulationsCount: number }>().props;
 47→    const [activeSpecies, setActiveSpecies] = useState<string | null>(null);
 48→
 49→    const subExploitations = exploitation?.sub_exploitations ?? [];
 50→    const availableSpecies = [...new Set(subExploitations.map((s) => s.species))];
 51→    const filteredSubs = activeSpecies
 52→        ? subExploitations.filter((s) => s.species === activeSpecies)
 53→        : subExploitations;
 54→
 55→    return (
 56→        <AppLayout breadcrumbs={breadcrumbs}>
