101→                                    species={sub.species}
102→                                    exploitationType={sub.exploitation_type}
103→                                    zootechnicalClassification={sub.zootechnical_classification}
104→                                    productiveSystem={sub.productive_system}
105→                                    currentCapacity={sub.current_capacity}
106→                                    maxCapacity={sub.max_capacity}
107→                                    sustainability={sub.sustainability}
108→                                    selfConsumption={sub.self_consumption}
109→                                    animalsCount={sub.animals_count}
110→                                />
