  6→interface Animal {
  7→    id: number;
  8→    crotal_code: string;
  9→    breed: string;
 10→    sex: string;
 11→    birth_date: string;
 12→}
 13→
 14→interface CampaignAnimal {
 15→    id: number;
 16→    status: 'pending' | 'sampled' | 'immobilized';
 17→    immobilization_reason: string | null;
 18→    animal: Animal;
 19→}
 20→
 21→interface Campaign {
 22→    id: number;
 23→    name: string;
 24→    status: string;
 25→    start_date: string;
 26→    end_date: string;
 27→    total_animals: number;
 28→    sampled_animals: number;
 29→    campaign_animals: CampaignAnimal[];
 30→}
 31→
 32→interface Props {
 33→    campaign: Campaign;
 34→}
 35→
 36→const statusConfig = {
 37→    pending: { label: 'Pendiente', icon: Clock, color: 'text-[#E65100]', bg: 'bg-[#FFF3E0]' },
 38→    sampled: { label: 'Muestreado', icon: CheckCircle2, color: 'text-[#2E7D32]', bg: 'bg-[#E8F5E9]' },
 39→    immobilized: { label: 'Inmovilizado', icon: ShieldAlert, color: 'text-[#E53935]', bg: 'bg-[#FFEBEE]' },
 40→};
 41→
 42→function AnimalCard({ item }: { item: CampaignAnimal }) {
 43→    const config = statusConfig[item.status];
 44→    const Icon = config.icon;
 45→    const age = Math.floor((Date.now() - new Date(item.animal.birth_date).getTime()) / (365.25 * 24 * 60 * 60 * 1000));
 46→
 47→    return (
 48→        <div className="flex items-center gap-3 border-2 border-black p-3">
 49→            <div className={`flex size-8 items-center justify-center ${config.bg}`}>
 50→                <Icon className={`size-4 ${config.color}`} />
 51→            </div>
 52→            <div className="flex-1">
 53→                <p className="text-sm font-bold">{item.animal.crotal_code}</p>
 54→                <p className="text-xs text-[#757575]">{item.animal.breed} · {item.animal.sex === 'female' ? 'Hembra' : 'Macho'} · {age} años</p>
 55→                {item.immobilization_reason && (
 56→                    <p className="mt-1 text-xs font-medium text-[#E53935]">{item.immobilization_reason}</p>
 57→                )}
 58→            </div>
 59→            <span className={`px-2 py-0.5 text-xs font-bold ${config.bg} ${config.color}`}>{config.label}</span>
 60→        </div>
 61→    );
 62→}
