 64→export default function CampaignShow({ campaign }: Props) {
 65→    const breadcrumbs: BreadcrumbItem[] = [
 66→        { title: 'Mi Explotación', href: '/dashboard' },
 67→        { title: 'Normativa', href: '/normativa' },
