 69→    ];
 70→
 71→    const pending = campaign.campaign_animals.filter((ca) => ca.status === 'pending');
 72→    const sampled = campaign.campaign_animals.filter((ca) => ca.status === 'sampled');
 73→    const immobilized = campaign.campaign_animals.filter((ca) => ca.status === 'immobilized');
 74→    const progress = campaign.total_animals > 0 ? (campaign.sampled_animals / campaign.total_animals) * 100 : 0;
 75→
 76→    return (
 77→        <AppLayout breadcrumbs={breadcrumbs}>
