 8→
 9→class SanitaryCampaignController extends Controller
10→{
11→    public function show(SanitaryCampaign $sanitaryCampaign): Response
12→    {
13→        $sanitaryCampaign->load(['campaignAnimals.animal', 'exploitation']);
14→
15→        $animals = $sanitaryCampaign->campaignAnimals->groupBy('status');
16→
17→        return Inertia::render('normativa/campanas/show', [
18→            'campaign' => $sanitaryCampaign,
19→            'animals' => [
