 70→function daysUntil(dateString: string): string | null {
 71→    const now = new Date();
 72→    const date = new Date(dateString);
 73→    const diffMs = date.getTime() - now.getTime();
 74→    const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
 75→
 76→    if (days < 0) return 'Vencido';
 77→    if (days === 0) return 'Hoy';
 78→    if (days === 1) return 'Mañana';
