 14→
 15→const speciesLabels: Record<string, string> = {
 16→    bovine: 'Bovino',
 17→    ovine: 'Ovino',
 18→    caprine: 'Caprino',
 19→    porcine: 'Porcino',
 20→    equine: 'Equino',
 21→};
