 23→const speciesHeaderColors: Record<string, string> = {
 24→    bovine: 'bg-[#E53935]',
 25→    ovine: 'bg-black',
 26→    caprine: 'bg-black',
 27→    porcine: 'bg-neutral-700',
 28→    equine: 'bg-amber-900',
 29→};
 30→
 31→function getCapacityColor(current: number, max: number): string {
 32→    const ratio = max > 0 ? current / max : 0;
 33→    if (ratio > 0.8) return 'bg-[#E53935]';
 34→    if (ratio > 0.6) return 'bg-amber-500';
 35→    return 'bg-[#2E7D32]';
 36→}
 37→
 38→function getSustainabilityStyle(sustainability: string | null): { bg: string; text: string; hasIcon: boolean } {
 39→    switch (sustainability?.toLowerCase()) {
 40→        case 'ecológico':
 41→            return { bg: 'bg-[#2E7D32] text-white', text: 'Ecológico', hasIcon: true };
 42→        case 'integrado':
 43→            return { bg: 'bg-[#F9A825] text-black', text: 'Integrado', hasIcon: false };
 44→        default:
 45→            return { bg: 'bg-neutral-200 text-neutral-600', text: sustainability ?? 'Convencional', hasIcon: false };
 46→    }
 47→}
 48→
 49→export function SubExploitationCard({
 50→    species,
 51→    exploitationType,
 52→    zootechnicalClassification,
 53→    productiveSystem,
 54→    currentCapacity,
 55→    maxCapacity,
 56→    sustainability,
 57→    selfConsumption,
 58→    animalsCount,
 59→}: SubExploitationCardProps) {
 60→    const label = speciesLabels[species] ?? species;
 61→    const headerColor = speciesHeaderColors[species] ?? 'bg-black';
 62→    const capacityColor = getCapacityColor(currentCapacity, maxCapacity);
 63→    const capacityPercent = maxCapacity > 0 ? Math.min((currentCapacity / maxCapacity) * 100, 100) : 0;
 64→    const sustainabilityStyle = getSustainabilityStyle(sustainability);
 65→
 66→    return (
 67→        <div className="overflow-hidden rounded-lg border-2 border-black">
 68→            {/* Header */}
 69→            <div className={`${headerColor} px-4 py-3.5 text-white`}>
 70→                <p className="text-[15px] font-bold">
 71→                    {label} · {zootechnicalClassification}
 72→                </p>
 73→                <p className="text-xs font-medium opacity-80">{exploitationType}</p>
 74→            </div>
 75→
 76→            {/* Body */}
 77→            <div className="flex flex-col gap-3 p-4">
 78→                {/* Sistema productivo */}
 79→                <div className="flex items-center justify-between">
 80→                    <span className="text-[13px] font-medium text-neutral-500">Sistema productivo</span>
 81→                    <span className="text-[13px] font-bold">{productiveSystem}</span>
 82→                </div>
 83→
 84→                {/* Capacidad */}
 85→                <div className="flex flex-col gap-1.5">
 86→                    <div className="flex items-center justify-between">
 87→                        <span className="text-[13px] font-medium text-neutral-500">Capacidad</span>
 88→                        <span className="text-[13px] font-bold">
 89→                            {currentCapacity} / {maxCapacity}
 90→                        </span>
 91→                    </div>
 92→                    <div className="h-2 w-full rounded-sm bg-neutral-100">
 93→                        <div
 94→                            className={`h-2 rounded-sm ${capacityColor}`}
 95→                            style={{ width: `${capacityPercent}%` }}
 96→                        />
 97→                    </div>
 98→                </div>
 99→
100→                {/* Badges */}
101→                <div className="flex flex-wrap gap-2">
102→                    {sustainability && (
103→                        <span
