import { ChevronRight, Leaf } from 'lucide-react';

type SubExploitationCardProps = {
    species: string;
    exploitationType: string;
    zootechnicalClassification: string;
    productiveSystem: string;
    currentCapacity: number;
    maxCapacity: number;
    sustainability: string | null;
    selfConsumption: boolean;
    animalsCount: number;
};

const speciesLabels: Record<string, string> = {
    bovine: 'Bovino',
    ovine: 'Ovino',
    caprine: 'Caprino',
    porcine: 'Porcino',
    equine: 'Equino',
};

const speciesHeaderColors: Record<string, string> = {
    bovine: 'bg-[#E53935]',
    ovine: 'bg-black',
    caprine: 'bg-black',
    porcine: 'bg-neutral-700',
    equine: 'bg-amber-900',
};

function getCapacityColor(current: number, max: number): string {
    const ratio = max > 0 ? current / max : 0;
    if (ratio > 0.8) return 'bg-[#E53935]';
    if (ratio > 0.6) return 'bg-amber-500';
    return 'bg-[#2E7D32]';
}

function getSustainabilityStyle(sustainability: string | null): { bg: string; text: string; hasIcon: boolean } {
    switch (sustainability?.toLowerCase()) {
        case 'ecológico':
            return { bg: 'bg-[#2E7D32] text-white', text: 'Ecológico', hasIcon: true };
        case 'integrado':
            return { bg: 'bg-[#F9A825] text-black', text: 'Integrado', hasIcon: false };
        default:
            return { bg: 'bg-neutral-200 text-neutral-600', text: sustainability ?? 'Convencional', hasIcon: false };
    }
}

export function SubExploitationCard({
    species,
    exploitationType,
    zootechnicalClassification,
    productiveSystem,
    currentCapacity,
    maxCapacity,
    sustainability,
    selfConsumption,
    animalsCount,
}: SubExploitationCardProps) {
    const label = speciesLabels[species] ?? species;
    const headerColor = speciesHeaderColors[species] ?? 'bg-black';
    const capacityColor = getCapacityColor(currentCapacity, maxCapacity);
    const capacityPercent = maxCapacity > 0 ? Math.min((currentCapacity / maxCapacity) * 100, 100) : 0;
    const sustainabilityStyle = getSustainabilityStyle(sustainability);

    return (
        <div className="overflow-hidden rounded-lg border-2 border-black">
            {/* Header */}
            <div className={`${headerColor} px-4 py-3.5 text-white`}>
                <p className="text-[15px] font-bold">
                    {label} · {zootechnicalClassification}
                </p>
                <p className="text-xs font-medium opacity-80">{exploitationType}</p>
            </div>

            {/* Body */}
            <div className="flex flex-col gap-3 p-4">
                {/* Sistema productivo */}
                <div className="flex items-center justify-between">
                    <span className="text-[13px] font-medium text-neutral-500">Sistema productivo</span>
                    <span className="text-[13px] font-bold">{productiveSystem}</span>
                </div>

                {/* Capacidad */}
                <div className="flex flex-col gap-1.5">
                    <div className="flex items-center justify-between">
                        <span className="text-[13px] font-medium text-neutral-500">Capacidad</span>
                        <span className="text-[13px] font-bold">
                            {currentCapacity} / {maxCapacity}
                        </span>
                    </div>
                    <div className="h-2 w-full rounded-sm bg-neutral-100">
                        <div
                            className={`h-2 rounded-sm ${capacityColor}`}
                            style={{ width: `${capacityPercent}%` }}
                        />
                    </div>
                </div>

                {/* Badges */}
                <div className="flex flex-wrap gap-2">
                    {sustainability && (
                        <span
                            className={`inline-flex items-center gap-1 rounded-sm px-2.5 py-1 text-[11px] font-bold ${sustainabilityStyle.bg}`}
                        >
                            {sustainabilityStyle.hasIcon && <Leaf className="size-3" />}
                            {sustainabilityStyle.text}
                        </span>
                    )}
                    <span className="inline-flex items-center rounded-sm border border-neutral-300 px-2.5 py-1 text-[11px] font-semibold text-neutral-500">
                        Autoconsumo: {selfConsumption ? 'SÍ' : 'NO'}
                    </span>
                </div>

                {/* Divider */}
                <div className="h-px w-full bg-neutral-100" />

                {/* Footer */}
                <div className="flex items-center justify-between">
                    <span className="text-[13px] font-semibold">Censo: {animalsCount} animales</span>
                    <button className="flex items-center gap-1 text-[13px] font-semibold text-[#E53935]">
                        Ver detalle
                        <ChevronRight className="size-4" />
                    </button>
                </div>
            </div>
        </div>
    );
}

