import { queryParams, type RouteQueryOptions, type RouteDefinition, applyUrlDefaults } from './../../../../wayfinder'
/**
* @see \App\Http\Controllers\SubExploitationController::show
* @see app/Http/Controllers/SubExploitationController.php:11
* @route '/subexplotaciones/{subExploitation}'
*/
export const show = (args: { subExploitation: number | { id: number } } | [subExploitation: number | { id: number } ] | number | { id: number }, options?: RouteQueryOptions): RouteDefinition<'get'> => ({
    url: show.url(args, options),
    method: 'get',
})

show.definition = {
    methods: ["get","head"],
    url: '/subexplotaciones/{subExploitation}',
} satisfies RouteDefinition<["get","head"]>

/**
* @see \App\Http\Controllers\SubExploitationController::show
* @see app/Http/Controllers/SubExploitationController.php:11
* @route '/subexplotaciones/{subExploitation}'
*/
show.url = (args: { subExploitation: number | { id: number } } | [subExploitation: number | { id: number } ] | number | { id: number }, options?: RouteQueryOptions) => {
    if (typeof args === 'string' || typeof args === 'number') {
        args = { subExploitation: args }
    }

    if (typeof args === 'object' && !Array.isArray(args) && 'id' in args) {
        args = { subExploitation: args.id }
    }

    if (Array.isArray(args)) {
        args = {
            subExploitation: args[0],
        }
    }

    args = applyUrlDefaults(args)

    const parsedArgs = {
        subExploitation: typeof args.subExploitation === 'object'
        ? args.subExploitation.id
        : args.subExploitation,
    }

    return show.definition.url
            .replace('{subExploitation}', parsedArgs.subExploitation.toString())
            .replace(/\/+$/, '') + queryParams(options)
}

/**
* @see \App\Http\Controllers\SubExploitationController::show
* @see app/Http/Controllers/SubExploitationController.php:11
* @route '/subexplotaciones/{subExploitation}'
*/
show.get = (args: { subExploitation: number | { id: number } } | [subExploitation: number | { id: number } ] | number | { id: number }, options?: RouteQueryOptions): RouteDefinition<'get'> => ({
    url: show.url(args, options),
    method: 'get',
})

/**
* @see \App\Http\Controllers\SubExploitationController::show
* @see app/Http/Controllers/SubExploitationController.php:11
* @route '/subexplotaciones/{subExploitation}'
*/
show.head = (args: { subExploitation: number | { id: number } } | [subExploitation: number | { id: number } ] | number | { id: number }, options?: RouteQueryOptions): RouteDefinition<'head'> => ({
    url: show.url(args, options),
    method: 'head',
})

const SubExploitationController = { show }

export default SubExploitationController

